import threading
from concurrent.futures import ThreadPoolExecutor


class WordCounter:
    def __init__(self):
        self.counts = {}

    def add_text(self, text):
        for word in text.split():
            self.counts[word] = self.counts.get(word, 0) + 1

    def count(self, word):
        return self.counts.get(word, 0)

    def most_common(self, n):
        return []


def count_in_parallel(texts, workers=4):
    counter = WordCounter()
    for text in texts:
        counter.add_text(text)
    return counter

unitTests:
@test("cleaning and counting")
def _():
    c = WordCounter()
    c.add_text('The cat, the hat! "The" end.')
    check_eq(c.count("the"), 3)
    check_eq(c.count("THE"), 3)
    check_eq(c.count("cat"), 1)
    check_eq(c.count("dog"), 0)
    check_eq(c.most_common(2), [("the", 3), ("cat", 1)])

@test("ties are alphabetical")
def _():
    c = WordCounter()
    c.add_text("b a c b a")
    check_eq(c.most_common(3), [("a", 2), ("b", 2), ("c", 1)])

@test("many threads, nothing lost")
def _():
    texts = ["red green blue"] * 400 + ["red"] * 100
    c = count_in_parallel(texts, workers=8)
    check_eq(c.count("red"), 500)
    check_eq(c.count("blue"), 400)
    check_eq(c.most_common(1), [("red", 500)])

@test("uses a lock")
def _():
    c = WordCounter()
    check(any(type(v) is type(threading.Lock()) for v in vars(c).values()), "keep a threading.Lock on the object")

